"""Record the exact tested V24 artifact and its 36 independent release checks."""
from pathlib import Path
import hashlib,json
R=Path(__file__).resolve().parents[2];O=R/'output/elyndor/pixellab-v24'
def read(p):return json.loads((O/p).read_text(encoding='utf-8'))
sha=hashlib.sha256((R/'index.html').read_bytes()).hexdigest();reg=read('regression.json');source=json.loads((R/'output/elyndor/continuous-standalone-audit.json').read_text(encoding='utf-8'))
assert reg['sha256']==source['sha256']==sha and source['sourceMatchesArtifact'] and len(reg['checks'])==31 and all(q['pass']for q in reg['checks'])
proof={name:read(path) for name,path in {'districts':'revision/report.json','clarity':'clarity/report.json','endurance':'endurance/report.json','resident':'resident-navigation/report.json','cutaway':'cutaway/report.json'}.items()}
assert all(p['pass'] and p['sha256']==sha for p in proof.values())
campaign=read('campaign/report.json');assert campaign['campaign']['final']=='complete' and not campaign['errors']
r=json.loads((R/'release.json').read_text(encoding='utf-8'));r['release']='elyndor-alpha-1.0-2026-10-29-atmosphere-v24';r['artifact']={'file':'index.html','bytes':(R/'index.html').stat().st_size,'sha256':sha,'offline':True};r['githubHistory']['previousRelease']='7eef655522ba23b4551c7aeb892935296cb1dcd5'
r['changes']=['Lower exploration camera places the west bridge approach at screen southwest; controls, picking, sprites and occlusion use the same view matrix','All fifteen POIs have 2.19–6.23 times their original exploration area, with preserved story courts, wooded approaches, separated floor exits, residential plots and matching local-map paths','New original PixelLab gold compass, map/satchel/party/journal icons and ink/gold panels are integrated into the accessible mouse-and-keyboard HUD','Selected native PixelLab limestone, slate, lime plaster and olive foliage replace key world materials; structural paving preserves crisp joints instead of blending offset stone patterns','Continuous physical roof UVs, correct upward porch faces, detailed west façades and gable joinery improve architecture; exact duplicate triangles are removed before batching','Depth-tested world-space light shafts sample the moving cloud field; warm directional light, balanced sky fill and world-space dust extend to every outdoor map','Instanced folded canopy leaves add real geometry while shared materials, static transforms, padded culling and budgeted NPC route jobs preserve sustained performance','Brookstead’s upper trail uses a continuous terrain grade; river-bank, stair-rail and harbor approaches have been individually corrected and audited','Existing full story progression, seven interiors, side-on combat, voiced dialogue, three record slots, entrance/inn saves and inn recovery remain available']
c=proof['clarity']['graphics'];r['graphics']={'sceneSamples':c['samples'],'worldAnisotropy':c['worldAnisotropy'],'spritesKeepNativeNearestFiltering':c['spriteNearest'],'camera':{'yawDegrees':c['yaw'],'pitchDegrees':c['pitch']},'fullSceneDepthBlur':False,'balancedPixelCeiling':3700000,'highPixelCeiling':5500000,'sourceArtRegenerated':True,'newSelectedAssets':10,'generator':'PixelLab MCP'}
r['validation']={'checks':reg['checks']+[{'name':k,'pass':True}for k in proof],'sourceMatchesArtifact':True,'expandedLocationsAndInterface':proof['districts'],'sharpRenderingAndControls':proof['clarity'],'endurance':proof['endurance'],'residentNavigation':proof['resident'],'locations':read('locations/report.json'),'services':read('services/report.json'),'storyProgressionSteps':len(campaign['campaign']['log']),'storyBattles':len(campaign['campaign']['battles']),'restoredLights':len(campaign['campaign']['restored']),'saveLoad':campaign['persistence']}
r['performance']={'nativeScenarios':read('performance/native.json'),'extended1080p':proof['endurance'],'repeatedDryPlay':read('soak-release-dry.json'),'repeatedStormPlay':read('soak-release-storm.json'),'pump':read('pump-fixed.json'),'tutorial':read('onboarding-performance.json'),'combat':read('combat-profile-final.json'),'atlas':read('atlas-performance.json'),'scope':proof['endurance']['scope']}
capture=read('atmosphere/report.json');assert capture['pass'] and capture['sha256']==sha;r['validation']['staticWorldAndPresentationCapture']=capture
r['validation']['buildingVisibilityRestoration']=proof['cutaway'];r['changes'].append('Building cutaway hooks install once and restore their draw ranges correctly, preventing houses from remaining invisible after camera transitions; eight repeated hide/reveal cycles pass')
initial=(O/'resident-navigation-final.log').read_text(encoding='utf-8',errors='replace')
for line in initial.splitlines():
 if line.startswith('{"sha256"'):
  probe=json.loads(line)
  if probe.get('sha256')==sha and not probe.get('pass'):
   r['performance']['initialResidentProbe']=probe;r['performance']['residentTimingNote']=f"An initial probe exceeded its 6 ms maximum-slice assertion once ({probe['test']['planner']['maxSliceMs']:.1f} ms); an unchanged repeat measured {proof['resident']['test']['planner']['maxSliceMs']:.1f} ms. Frame scheduling maxima are retained in reports; this is not a guarantee of zero frame-time outliers."
(R/'release.json').write_text(json.dumps(r,indent=2,ensure_ascii=False)+'\n',encoding='utf-8',newline='\n');print(json.dumps({'release':r['release'],'sha256':sha,'checks':36,'bytes':r['artifact']['bytes']}))
